#include <windows.h>
#include <ncrypt.h>
#include <bcrypt.h>
#include <wincrypt.h>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#pragma comment(lib,"ncrypt.lib")
#pragma comment(lib,"bcrypt.lib")
#pragma comment(lib,"crypt32.lib")

namespace {
constexpr char kProtocol[]="CIEAV_WINDOWS_TPM_NATIVE_ATTESTATION_V1";
constexpr char kAikEku[]="2.23.133.8.3";
constexpr size_t kMaxClaimBytes=256*1024;

struct NcryptHandle{NCRYPT_HANDLE h{0};explicit NcryptHandle(NCRYPT_HANDLE v=0):h(v){}~NcryptHandle(){if(h)NCryptFreeObject(h);}NcryptHandle(const NcryptHandle&)=delete;NcryptHandle& operator=(const NcryptHandle&)=delete;};
struct CertHandle{PCCERT_CONTEXT p{nullptr};explicit CertHandle(PCCERT_CONTEXT v=nullptr):p(v){}~CertHandle(){if(p)CertFreeCertificateContext(p);}CertHandle(const CertHandle&)=delete;CertHandle& operator=(const CertHandle&)=delete;};
struct ChainHandle{PCCERT_CHAIN_CONTEXT p{nullptr};explicit ChainHandle(PCCERT_CHAIN_CONTEXT v=nullptr):p(v){}~ChainHandle(){if(p)CertFreeCertificateChain(p);}ChainHandle(const ChainHandle&)=delete;ChainHandle& operator=(const ChainHandle&)=delete;};
struct BcryptKey{BCRYPT_KEY_HANDLE h{nullptr};~BcryptKey(){if(h)BCryptDestroyKey(h);}BcryptKey(const BcryptKey&)=delete;BcryptKey& operator=(const BcryptKey&)=delete;};

[[noreturn]] void failStatus(const char* op,SECURITY_STATUS s){std::ostringstream o;o<<op<<" failed: 0x"<<std::hex<<std::uppercase<<static_cast<unsigned long>(s);throw std::runtime_error(o.str());}
void check(const char* op,SECURITY_STATUS s){if(s!=ERROR_SUCCESS)failStatus(op,s);}
void checkNt(const char* op,NTSTATUS s){if(s<0){std::ostringstream o;o<<op<<" failed: 0x"<<std::hex<<std::uppercase<<static_cast<unsigned long>(s);throw std::runtime_error(o.str());}}
std::wstring widen(const std::string& in){if(in.empty())throw std::runtime_error("empty UTF-8 value");int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,in.data(),static_cast<int>(in.size()),nullptr,0);if(n<=0)throw std::runtime_error("invalid UTF-8");std::wstring out(static_cast<size_t>(n),L'\0');if(MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,in.data(),static_cast<int>(in.size()),out.data(),n)<=0)throw std::runtime_error("invalid UTF-8");return out;}
std::string jsonEscape(const std::string& s){std::ostringstream o;for(unsigned char c:s){switch(c){case '"':o<<"\\\"";break;case '\\':o<<"\\\\";break;case '\n':o<<"\\n";break;case '\r':o<<"\\r";break;case '\t':o<<"\\t";break;default:if(c<0x20)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<static_cast<int>(c);else o<<c;}}return o.str();}
std::string b64url(const unsigned char* data,size_t n){static constexpr char table[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";std::string out;out.reserve((n*4+2)/3);for(size_t i=0;i<n;i+=3){unsigned v=static_cast<unsigned>(data[i])<<16;if(i+1<n)v|=static_cast<unsigned>(data[i+1])<<8;if(i+2<n)v|=data[i+2];out.push_back(table[(v>>18)&63]);out.push_back(table[(v>>12)&63]);if(i+1<n)out.push_back(table[(v>>6)&63]);if(i+2<n)out.push_back(table[v&63]);}return out;}
int b64digit(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='-')return 62;if(c=='_')return 63;return -1;}
std::vector<unsigned char> b64urlDecode(const std::string& in){if(in.empty()||in.size()%4==1)throw std::runtime_error("invalid base64url");std::vector<unsigned char> out;out.reserve(in.size()*3/4);unsigned acc=0;int bits=0;for(char c:in){int d=b64digit(c);if(d<0)throw std::runtime_error("invalid base64url");acc=(acc<<6)|static_cast<unsigned>(d);bits+=6;if(bits>=8){bits-=8;out.push_back(static_cast<unsigned char>((acc>>bits)&0xffu));}}if(out.empty())throw std::runtime_error("empty decoded value");return out;}
void assertKeyName(const std::string& name){if(name.empty()||name.size()>200)throw std::runtime_error("invalid key name");}

NCRYPT_PROV_HANDLE openPlatformProvider(){NCRYPT_PROV_HANDLE p=0;check("NCryptOpenStorageProvider",NCryptOpenStorageProvider(&p,MS_PLATFORM_CRYPTO_PROVIDER,0));DWORD impl=0,cb=0;check("NCryptGetProperty(Impl Type)",NCryptGetProperty(p,NCRYPT_IMPL_TYPE_PROPERTY,reinterpret_cast<PBYTE>(&impl),sizeof(impl),&cb,0));if((impl&NCRYPT_IMPL_HARDWARE_FLAG)==0||(impl&NCRYPT_IMPL_SOFTWARE_FLAG)!=0){NCryptFreeObject(p);throw std::runtime_error("Microsoft Platform Crypto Provider is not reporting an exclusive hardware implementation");}return p;}
NCRYPT_KEY_HANDLE openKey(NCRYPT_PROV_HANDLE p,const std::string& name,bool machine){assertKeyName(name);NCRYPT_KEY_HANDLE k=0;DWORD flags=NCRYPT_SILENT_FLAG|(machine?NCRYPT_MACHINE_KEY_FLAG:0);check("NCryptOpenKey",NCryptOpenKey(p,&k,widen(name).c_str(),0,flags));return k;}
DWORD exportPolicy(NCRYPT_KEY_HANDLE k){DWORD v=0,cb=0;SECURITY_STATUS s=NCryptGetProperty(k,NCRYPT_EXPORT_POLICY_PROPERTY,reinterpret_cast<PBYTE>(&v),sizeof(v),&cb,0);if(s==NTE_NOT_FOUND)return 0;check("NCryptGetProperty(Export Policy)",s);return v;}
void assertNonExportable(NCRYPT_KEY_HANDLE k){DWORD p=exportPolicy(k);if(p&(NCRYPT_ALLOW_EXPORT_FLAG|NCRYPT_ALLOW_PLAINTEXT_EXPORT_FLAG|NCRYPT_ALLOW_ARCHIVING_FLAG|NCRYPT_ALLOW_PLAINTEXT_ARCHIVING_FLAG))throw std::runtime_error("private export policy is enabled");}
std::vector<unsigned char> propertyBytes(NCRYPT_KEY_HANDLE k,LPCWSTR name){DWORD cb=0;check("NCryptGetProperty(size)",NCryptGetProperty(k,name,nullptr,0,&cb,0));if(cb==0||cb>1024*1024)throw std::runtime_error("invalid property length");std::vector<unsigned char> out(cb);check("NCryptGetProperty",NCryptGetProperty(k,name,out.data(),cb,&cb,0));out.resize(cb);return out;}
std::vector<unsigned char> exportBlob(NCRYPT_KEY_HANDLE k,LPCWSTR type){DWORD cb=0;check("NCryptExportKey(size)",NCryptExportKey(k,0,type,nullptr,nullptr,0,&cb,0));if(cb==0||cb>64*1024)throw std::runtime_error("invalid public key blob length");std::vector<unsigned char> out(cb);check("NCryptExportKey",NCryptExportKey(k,0,type,nullptr,out.data(),cb,&cb,0));out.resize(cb);return out;}
std::string rsaJwk(NCRYPT_KEY_HANDLE k){auto blob=exportBlob(k,BCRYPT_RSAPUBLIC_BLOB);if(blob.size()<sizeof(BCRYPT_RSAKEY_BLOB))throw std::runtime_error("invalid RSA public blob");auto* h=reinterpret_cast<const BCRYPT_RSAKEY_BLOB*>(blob.data());if(h->Magic!=BCRYPT_RSAPUBLIC_MAGIC||h->BitLength<2048||h->cbPublicExp==0||h->cbModulus<256)throw std::runtime_error("RSA key is below the required strength");size_t need=sizeof(BCRYPT_RSAKEY_BLOB)+static_cast<size_t>(h->cbPublicExp)+static_cast<size_t>(h->cbModulus);if(need>blob.size())throw std::runtime_error("truncated RSA public blob");const unsigned char* e=blob.data()+sizeof(BCRYPT_RSAKEY_BLOB);const unsigned char* n=e+h->cbPublicExp;std::ostringstream o;o<<"{\"kty\":\"RSA\",\"n\":\""<<b64url(n,h->cbModulus)<<"\",\"e\":\""<<b64url(e,h->cbPublicExp)<<"\"}";return o.str();}
std::string ecJwk(NCRYPT_KEY_HANDLE k){auto blob=exportBlob(k,BCRYPT_ECCPUBLIC_BLOB);if(blob.size()<sizeof(BCRYPT_ECCKEY_BLOB))throw std::runtime_error("invalid ECC public blob");auto* h=reinterpret_cast<const BCRYPT_ECCKEY_BLOB*>(blob.data());if(h->dwMagic!=BCRYPT_ECDSA_PUBLIC_P256_MAGIC||h->cbKey!=32)throw std::runtime_error("key is not ECDSA P-256");if(sizeof(BCRYPT_ECCKEY_BLOB)+64>blob.size())throw std::runtime_error("truncated ECC public blob");const unsigned char* x=blob.data()+sizeof(BCRYPT_ECCKEY_BLOB);const unsigned char* y=x+32;std::ostringstream o;o<<"{\"kty\":\"EC\",\"crv\":\"P-256\",\"x\":\""<<b64url(x,32)<<"\",\"y\":\""<<b64url(y,32)<<"\"}";return o.str();}

void assertAikCertificate(NCRYPT_KEY_HANDLE aik,const std::vector<unsigned char>& der){CertHandle cert(CertCreateCertificateContext(X509_ASN_ENCODING|PKCS_7_ASN_ENCODING,der.data(),static_cast<DWORD>(der.size())));if(!cert.p)throw std::runtime_error("AIK certificate parsing failed");BcryptKey certKey;if(!CryptImportPublicKeyInfoEx2(X509_ASN_ENCODING|PKCS_7_ASN_ENCODING,&cert.p->pCertInfo->SubjectPublicKeyInfo,0,nullptr,&certKey.h))throw std::runtime_error("AIK certificate public key import failed");DWORD certBlobSize=0;checkNt("BCryptExportKey(AIK cert size)",BCryptExportKey(certKey.h,nullptr,BCRYPT_RSAPUBLIC_BLOB,nullptr,0,&certBlobSize,0));std::vector<unsigned char> certBlob(certBlobSize);checkNt("BCryptExportKey(AIK cert)",BCryptExportKey(certKey.h,nullptr,BCRYPT_RSAPUBLIC_BLOB,certBlob.data(),certBlobSize,&certBlobSize,0));certBlob.resize(certBlobSize);auto aikBlob=exportBlob(aik,BCRYPT_RSAPUBLIC_BLOB);if(certBlob!=aikBlob)throw std::runtime_error("AIK certificate public key does not match AIK handle");LPSTR usages[1]={const_cast<LPSTR>(kAikEku)};CERT_CHAIN_PARA chainPara{};chainPara.cbSize=sizeof(chainPara);chainPara.RequestedUsage.dwType=USAGE_MATCH_TYPE_AND;chainPara.RequestedUsage.Usage.cUsageIdentifier=1;chainPara.RequestedUsage.Usage.rgpszUsageIdentifier=usages;PCCERT_CHAIN_CONTEXT rawChain=nullptr;DWORD flags=CERT_CHAIN_REVOCATION_CHECK_CHAIN_EXCLUDE_ROOT;if(!CertGetCertificateChain(nullptr,cert.p,nullptr,nullptr,&chainPara,flags,nullptr,&rawChain))throw std::runtime_error("AIK certificate chain build failed");ChainHandle chain(rawChain);CERT_CHAIN_POLICY_PARA policyPara{};policyPara.cbSize=sizeof(policyPara);CERT_CHAIN_POLICY_STATUS status{};status.cbSize=sizeof(status);if(!CertVerifyCertificateChainPolicy(CERT_CHAIN_POLICY_BASE,chain.p,&policyPara,&status))throw std::runtime_error("AIK certificate chain policy evaluation failed");if(status.dwError!=0){std::ostringstream o;o<<"AIK certificate chain is not trusted for TPM AIK EKU: 0x"<<std::hex<<std::uppercase<<status.dwError;throw std::runtime_error(o.str());}}

NCryptBufferDesc nonceParams(std::vector<unsigned char>& nonce,NCryptBuffer& buffer){buffer.cbBuffer=static_cast<ULONG>(nonce.size());buffer.BufferType=NCRYPTBUFFER_CLAIM_KEYATTESTATION_NONCE;buffer.pvBuffer=nonce.data();NCryptBufferDesc desc{};desc.ulVersion=NCRYPTBUFFER_VERSION;desc.cBuffers=1;desc.pBuffers=&buffer;return desc;}
std::vector<unsigned char> createClaim(NCRYPT_KEY_HANDLE subject,NCRYPT_KEY_HANDLE aik,std::vector<unsigned char>& nonce){NCryptBuffer b{};auto params=nonceParams(nonce,b);DWORD cb=0;check("NCryptCreateClaim(size)",NCryptCreateClaim(subject,aik,NCRYPT_CLAIM_AUTHORITY_AND_SUBJECT,&params,nullptr,0,&cb,0));if(cb==0||cb>kMaxClaimBytes)throw std::runtime_error("invalid key-attestation claim length");std::vector<unsigned char> claim(cb);check("NCryptCreateClaim",NCryptCreateClaim(subject,aik,NCRYPT_CLAIM_AUTHORITY_AND_SUBJECT,&params,claim.data(),cb,&cb,0));claim.resize(cb);return claim;}
void freeVerifyOutput(NCryptBufferDesc& output){if(!output.pBuffers)return;for(ULONG i=0;i<output.cBuffers;++i)if(output.pBuffers[i].pvBuffer)NCryptFreeBuffer(output.pBuffers[i].pvBuffer);NCryptFreeBuffer(output.pBuffers);output.pBuffers=nullptr;output.cBuffers=0;}
void verifyClaim(NCRYPT_KEY_HANDLE subject,NCRYPT_KEY_HANDLE aik,std::vector<unsigned char>& nonce,const std::vector<unsigned char>& claim){NCryptBuffer b{};auto params=nonceParams(nonce,b);NCryptBufferDesc output{};SECURITY_STATUS s=NCryptVerifyClaim(subject,aik,NCRYPT_CLAIM_AUTHORITY_AND_SUBJECT,&params,const_cast<PBYTE>(claim.data()),static_cast<DWORD>(claim.size()),&output,0);if(s!=ERROR_SUCCESS){freeVerifyOutput(output);failStatus("NCryptVerifyClaim",s);}freeVerifyOutput(output);}
std::vector<unsigned char> readClaimFile(const std::string& raw){std::filesystem::path p=std::filesystem::u8path(raw);if(!p.is_absolute())throw std::runtime_error("claim file path must be absolute");std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("claim file unavailable");f.seekg(0,std::ios::end);auto end=f.tellg();if(end<=0||static_cast<unsigned long long>(end)>kMaxClaimBytes)throw std::runtime_error("claim file length invalid");f.seekg(0,std::ios::beg);std::vector<unsigned char> out(static_cast<size_t>(end));f.read(reinterpret_cast<char*>(out.data()),static_cast<std::streamsize>(out.size()));if(!f)throw std::runtime_error("claim file read failed");return out;}
std::string argValue(int argc,char** argv,const std::string& name){for(int i=2;i+1<argc;++i)if(argv[i]==name)return argv[i+1];throw std::runtime_error("missing required argument: "+name);}
bool hasFlag(int argc,char** argv,const std::string& name){for(int i=2;i<argc;++i)if(argv[i]==name)return true;return false;}

int collect(int argc,char** argv){auto aikName=argValue(argc,argv,"--aik"),requestName=argValue(argc,argv,"--request-key"),consequenceName=argValue(argc,argv,"--consequence-key"),nonceText=argValue(argc,argv,"--nonce");bool aikMachine=!hasFlag(argc,argv,"--aik-user");auto nonce=b64urlDecode(nonceText);if(nonce.size()<16||nonce.size()>128)throw std::runtime_error("nonce must decode to 16..128 bytes");NcryptHandle provider(openPlatformProvider()),aik(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),aikName,aikMachine)),request(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),requestName,false)),consequence(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),consequenceName,false));assertNonExportable(static_cast<NCRYPT_KEY_HANDLE>(request.h));assertNonExportable(static_cast<NCRYPT_KEY_HANDLE>(consequence.h));auto cert=propertyBytes(static_cast<NCRYPT_KEY_HANDLE>(aik.h),NCRYPT_CERTIFICATE_PROPERTY);assertAikCertificate(static_cast<NCRYPT_KEY_HANDLE>(aik.h),cert);auto requestClaim=createClaim(static_cast<NCRYPT_KEY_HANDLE>(request.h),static_cast<NCRYPT_KEY_HANDLE>(aik.h),nonce),consequenceClaim=createClaim(static_cast<NCRYPT_KEY_HANDLE>(consequence.h),static_cast<NCRYPT_KEY_HANDLE>(aik.h),nonce);std::cout<<"{\"protocol\":\""<<kProtocol<<"\",\"operation\":\"collect\",\"provider\":\"TPM\",\"nativeProvider\":\"Microsoft Platform Crypto Provider\",\"hardwareBacked\":true,\"aikName\":\""<<jsonEscape(aikName)<<"\",\"aikMachineKey\":"<<(aikMachine?"true":"false")<<",\"nonce\":\""<<jsonEscape(nonceText)<<"\",\"aikCertificateDer\":\""<<b64url(cert.data(),cert.size())<<"\",\"aikPublicJwk\":"<<rsaJwk(static_cast<NCRYPT_KEY_HANDLE>(aik.h))<<",\"requestKey\":{\"keyName\":\""<<jsonEscape(requestName)<<"\",\"hardwareBacked\":true,\"exportable\":false,\"publicJwk\":"<<rsaJwk(static_cast<NCRYPT_KEY_HANDLE>(request.h))<<",\"claim\":\""<<b64url(requestClaim.data(),requestClaim.size())<<"\"},\"consequenceKey\":{\"keyName\":\""<<jsonEscape(consequenceName)<<"\",\"hardwareBacked\":true,\"exportable\":false,\"publicJwk\":"<<ecJwk(static_cast<NCRYPT_KEY_HANDLE>(consequence.h))<<",\"claim\":\""<<b64url(consequenceClaim.data(),consequenceClaim.size())<<"\"}}\n";return 0;}
int verify(int argc,char** argv){auto aikName=argValue(argc,argv,"--aik"),requestName=argValue(argc,argv,"--request-key"),consequenceName=argValue(argc,argv,"--consequence-key"),nonceText=argValue(argc,argv,"--nonce"),requestClaimPath=argValue(argc,argv,"--request-claim-file"),consequenceClaimPath=argValue(argc,argv,"--consequence-claim-file");bool aikMachine=!hasFlag(argc,argv,"--aik-user");auto nonce=b64urlDecode(nonceText);if(nonce.size()<16||nonce.size()>128)throw std::runtime_error("nonce must decode to 16..128 bytes");auto requestClaim=readClaimFile(requestClaimPath),consequenceClaim=readClaimFile(consequenceClaimPath);NcryptHandle provider(openPlatformProvider()),aik(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),aikName,aikMachine)),request(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),requestName,false)),consequence(openKey(static_cast<NCRYPT_PROV_HANDLE>(provider.h),consequenceName,false));assertNonExportable(static_cast<NCRYPT_KEY_HANDLE>(request.h));assertNonExportable(static_cast<NCRYPT_KEY_HANDLE>(consequence.h));auto cert=propertyBytes(static_cast<NCRYPT_KEY_HANDLE>(aik.h),NCRYPT_CERTIFICATE_PROPERTY);assertAikCertificate(static_cast<NCRYPT_KEY_HANDLE>(aik.h),cert);verifyClaim(static_cast<NCRYPT_KEY_HANDLE>(request.h),static_cast<NCRYPT_KEY_HANDLE>(aik.h),nonce,requestClaim);verifyClaim(static_cast<NCRYPT_KEY_HANDLE>(consequence.h),static_cast<NCRYPT_KEY_HANDLE>(aik.h),nonce,consequenceClaim);std::cout<<"{\"protocol\":\""<<kProtocol<<"\",\"operation\":\"verify\",\"provider\":\"TPM\",\"nativeProvider\":\"Microsoft Platform Crypto Provider\",\"verification\":\"VERIFIED\",\"hardwareBacked\":true,\"aikCertificateTrusted\":true,\"aikCertificateEku\":\""<<kAikEku<<"\",\"revocationChecked\":true,\"aikName\":\""<<jsonEscape(aikName)<<"\",\"aikMachineKey\":"<<(aikMachine?"true":"false")<<",\"nonce\":\""<<jsonEscape(nonceText)<<"\",\"aikCertificateDer\":\""<<b64url(cert.data(),cert.size())<<"\",\"aikPublicJwk\":"<<rsaJwk(static_cast<NCRYPT_KEY_HANDLE>(aik.h))<<",\"requestKey\":{\"keyName\":\""<<jsonEscape(requestName)<<"\",\"hardwareBacked\":true,\"exportable\":false,\"publicJwk\":"<<rsaJwk(static_cast<NCRYPT_KEY_HANDLE>(request.h))<<"},\"consequenceKey\":{\"keyName\":\""<<jsonEscape(consequenceName)<<"\",\"hardwareBacked\":true,\"exportable\":false,\"publicJwk\":"<<ecJwk(static_cast<NCRYPT_KEY_HANDLE>(consequence.h))<<"}}\n";return 0;}
}

int main(int argc,char** argv){try{if(argc<2){std::cerr<<"usage: cieav-windows-tpm-native-attestation <collect|verify> ...\n";return 2;}std::string cmd=argv[1];if(cmd=="collect")return collect(argc,argv);if(cmd=="verify")return verify(argc,argv);std::cerr<<"unsupported command\n";return 2;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 20;}}
